int find_power(int n, int p){
    int res = 0, tmp;
    for(int i = p; i <= n; i += p){
        tmp = i;
        while(tmp % p == 0){
            ++res;
            tmp /= p;
        }
    }
    return res;
}

int legendre(int n, int p){
    int res = 0;
    for(int i = p; i <= n; i *= p){
        res += n / i;
    }
    return res;
}
